"""Offline evaluator tests: transport evidence cannot be generated by the model."""
import asyncio
import json

import httpx
import pytest
from fastapi.testclient import TestClient

from second_opinion_gateway import create_app, _origin
from app.config import Settings
from app.main import create_app as demo_app
from app.prototype_provider import PrototypeRuntimeProvider
from test_prototype import remote

MODEL = 'nvidia/Nemotron-3-Ultra-550b-a55b'
VERDICT = {'status': 'agree', 'summary': 'The claim matches its citation.',
           'checked_claims': ['direction'], 'conflicts': []}
REQUEST = {'user_request': 'Which direction does the sign indicate?',
           'primary_model': {'model_id': 'zai-org/GLM-5.3-Flash'},
           'primary_output': {'parsed': True, 'raw_text': '{}'}}


def completion(verdict=None, **overrides):
    return {'id': 'chatcmpl-provider-123', 'model': MODEL,
            'choices': [{'finish_reason': 'stop', 'message': {'content': json.dumps(verdict or VERDICT)}}],
            'usage': {'prompt_tokens': 50, 'completion_tokens': 20, 'total_tokens': 70}, **overrides}


def client(monkeypatch, handler, key='test-secret'):
    monkeypatch.setenv('NEBIUS_API_KEY', key)
    monkeypatch.setenv('NEBIUS_BASE_URL', 'https://provider.test/v1/')
    monkeypatch.setenv('SECOND_OPINION_MODEL', MODEL)
    return TestClient(create_app(transport=httpx.MockTransport(handler)))


def test_evaluator_records_transport_evidence_and_keeps_input_in_data(monkeypatch):
    calls = []
    def handler(request):
        calls.append(request)
        assert str(request.url) == 'https://provider.test/v1/chat/completions'
        assert request.headers['Authorization'] == 'Bearer test-secret'
        body = json.loads(request.content)
        assert body['model'] == MODEL
        assert body['stream'] is False
        assert [item['role'] for item in body['messages']] == ['system', 'user']
        assert 'untrusted data' in body['messages'][0]['content']
        assert json.loads(body['messages'][1]['content'])['primary_output'] == REQUEST['primary_output']
        return httpx.Response(200, json=completion(), headers={'x-request-id': 'provider-request-456'})
    with client(monkeypatch, handler) as api:
        health = api.get('/health').json()
        assert health == {'status': 'ok', 'model': MODEL, 'configured': True, 'role': 'advisory_evaluator'}
        assert not calls  # Health never claims an authenticated inference happened.
        response = api.post('/v1/evaluate', json=REQUEST)
    assert response.status_code == 200
    result = response.json()
    assert result['status'] == 'agree'
    assert result['model'] == result['provider_model'] == MODEL
    assert result['provider'] == 'nebius'
    assert result['provider_origin'] == 'https://provider.test'
    assert result['response_id'] == 'chatcmpl-provider-123'
    assert result['provider_request_id'] == 'provider-request-456'
    assert result['usage'] == {'prompt_tokens': 50, 'completion_tokens': 20, 'total_tokens': 70}
    assert result['elapsed_ms'] >= 0
    assert 'test-secret' not in response.text
    assert len(calls) == 1


@pytest.mark.parametrize('url,expected', [
    ('https://user:secret@api.test:8443/private/token?key=secret#token', 'https://api.test:8443'),
    ('https://u:p@[2001:db8::1]:8443/private?secret=yes', 'https://[2001:db8::1]:8443'),
    ('https://api.test:443/v1/chat/completions', 'https://api.test'),
])
def test_provider_origin_redacts_secrets_and_preserves_ipv6(url, expected):
    assert _origin(httpx.URL(url)) == expected


@pytest.mark.parametrize('mutation', ['truncated', 'invalid-json', 'not-object', 'missing-choice',
                                     'bad-status', 'too-many-claims', 'spoof-evidence'])
def test_malformed_or_incomplete_opinions_fail_explicitly(monkeypatch, mutation):
    payload = completion()
    if mutation == 'truncated':
        payload['choices'][0]['finish_reason'] = 'length'
    elif mutation == 'invalid-json':
        payload['choices'][0]['message']['content'] = '{'
    elif mutation == 'not-object':
        payload = []
    elif mutation == 'missing-choice':
        payload['choices'] = []
    else:
        verdict = dict(VERDICT)
        if mutation == 'bad-status': verdict['status'] = 'allowed'
        if mutation == 'too-many-claims': verdict['checked_claims'] = ['claim'] * 31
        if mutation == 'spoof-evidence': verdict['response_id'] = 'invented-by-the-model'
        payload = completion(verdict)
    with client(monkeypatch, lambda request: httpx.Response(200, json=payload)) as api:
        response = api.post('/v1/evaluate', json=REQUEST)
    assert response.status_code == 502
    assert 'test-secret' not in response.text
    assert 'invented-by-the-model' not in response.text


@pytest.mark.parametrize('status', [401, 429, 500])
def test_provider_errors_are_sanitized_and_not_retried(monkeypatch, status):
    calls = []
    def handler(request):
        calls.append(request)
        return httpx.Response(status, text='test-secret private upstream body')
    with client(monkeypatch, handler) as api:
        response = api.post('/v1/evaluate', json=REQUEST)
    assert response.status_code == 502
    assert len(calls) == 1
    assert 'test-secret' not in response.text and 'private upstream' not in response.text


def test_missing_key_never_calls_provider(monkeypatch):
    def handler(request):
        pytest.fail('No request without credentials')
    with client(monkeypatch, handler, key='') as api:
        assert api.get('/health').json()['configured'] is False
        assert api.post('/v1/evaluate', json=REQUEST).status_code == 503


def test_timeout_never_retries_or_exposes_credentials(monkeypatch):
    calls = []
    def handler(request):
        calls.append(request)
        raise httpx.ReadTimeout('test-secret', request=request)
    with client(monkeypatch, handler) as api:
        response = api.post('/v1/evaluate', json=REQUEST)
    assert response.status_code == 502
    assert len(calls) == 1
    assert 'test-secret' not in response.text


def test_missing_provider_metadata_is_not_fabricated(monkeypatch):
    payload = completion(id=None, model=None, usage={'prompt_tokens': True, 'total_tokens': -1})
    with client(monkeypatch, lambda request: httpx.Response(200, json=payload)) as api:
        result = api.post('/v1/evaluate', json=REQUEST).json()
    assert result['model'] == MODEL  # Configured model, not proof of a provider-reported model.
    assert result['provider_model'] is None
    assert result['response_id'] is None and result['provider_request_id'] is None
    assert result['usage'] == {}


@pytest.mark.parametrize('guard', [True, False])
@pytest.mark.parametrize('opinion', ['agree', 'disagree', 'uncertain', 'error'])
def test_evaluator_cannot_override_policy_and_evidence_reaches_sse(guard, opinion):
    primary = remote(allow=False, policy=guard)
    requests = []
    def handler(request):
        requests.append(request)
        if request.url.path == '/health':
            return httpx.Response(200, json={'status': 'ready', 'model_loaded': True})
        if request.url.path == '/v1/analyze':
            return httpx.Response(200, json=primary)
        assert request.url.path == '/v1/evaluate'
        assert json.loads(request.content)['policy'] == primary['policy']
        if opinion == 'error':
            return httpx.Response(503, text='private upstream body')
        return httpx.Response(200, json={**VERDICT, 'status': opinion, 'model': MODEL,
            'provider': 'nebius', 'provider_origin': 'https://provider.test',
            'provider_model': MODEL, 'response_id': 'chatcmpl-proof',
            'provider_request_id': 'provider-proof', 'elapsed_ms': 42.5, 'usage': {'total_tokens': 70}})
    provider = PrototypeRuntimeProvider('http://primary.test', transport=httpx.MockTransport(handler),
                                        second_opinion_url='http://evaluator.test')
    with TestClient(demo_app(Settings(runtime='prototype'), provider)) as api:
        assert api.get('/api/health').json()['prototype']['second_opinion'] == {
            'configured': True, 'role': 'advisory_evaluator'}
        initial = api.post('/api/run', files={'image': ('scene.png', b'fake image', 'image/png')},
            data={'scenario_id': 'navigation-injection', 'guard_enabled': str(guard).lower(),
                  'user_request': 'Which direction does the exit sign indicate?'}).json()
        stream = api.get(f"/api/run/{initial['id']}/events").text
        snapshots = [json.loads(line[6:]) for line in stream.splitlines() if line.startswith('data: ')]
    final = snapshots[-1]
    assert final['status'] == 'completed'
    assert final['second_opinion']['status'] == opinion
    assert final['outcome']['status'] == ('blocked' if guard else 'executed')
    assert (final['decision'] or {}).get('result') == ('block' if guard else None)
    assert final['runtime_metadata']['policy'] == primary['policy']
    assert final['timings']['second_opinion_request_ms'] >= 0
    assert 'second_opinion.started' in [s['stage'] for s in snapshots]
    assert 'second_opinion.completed' in [s['stage'] for s in snapshots]
    assert [r.url.path for r in requests] == ['/health', '/v1/analyze', '/v1/evaluate']
    if opinion != 'error':
        assert final['second_opinion']['response_id'] == 'chatcmpl-proof'
        assert final['second_opinion']['provider_origin'] == 'https://provider.test'
        assert final['second_opinion']['provider_request_id'] == 'provider-proof'
        assert final['second_opinion']['elapsed_ms'] == 42.5
    else:
        assert final['second_opinion']['response_id'] is None
        assert 'private upstream body' not in stream
